### C++

```cpp
#include <bits/stdc++.h>
using namespace std;

// 执行一轮演化，返回新序列，参数changed指示是否发生变化
string apply_once(const string &s, bool &changed) {
    int n = (int)s.size();
    array<int, 26> freq{}, left{};
    for (char ch : s) ++freq[ch - 'a'];
    string res = s;
    changed = false;
    for (int i = 0; i < n; ++i) {
        int c = res[i] - 'a';
        if (left[c] == freq[c] - left[c] - 1) {
            --freq[c];
            int nc = (c + 1) % 26;
            res[i] = char('a' + nc);
            ++freq[nc];
            ++left[nc];
            changed = true;
        } else {
            ++left[c];
        }
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    cin >> q;
    while (q--) {
        int m, r;
        string z;
        cin >> m >> r >> z;

        deque<string> window;
        window.push_back(z);
        int done = 0;
        bool changed;
        while (done < r) {
            string nxt = apply_once(z, changed);
            ++done;
            if (!changed) {      // 已稳定
                z = nxt;
                break;
            }
            z.swap(nxt);
            window.push_back(z);
            if ((int)window.size() > 27) window.pop_front();
            if ((int)window.size() == 27 && window.front() == window.back()) {
                int rem = r - done;
                string s0 = window[0];
                string s1 = window[1];
                int add = rem % 26;
                for (int i = 0; i < m; ++i) {
                    if (s0[i] != s1[i]) {
                        z[i] = char('a' + (z[i] - 'a' + add) % 26);
                    }
                }
                break;
            }
        }
        cout << z << '\n';
    }
    return 0;
}
